1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.util.ArrayList;
5	import java.util.List;
6	import java.util.Map;
7	
8	import net.officefloor.plugin.variable.Out;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.escalation.OwnerFieldsValidationException;
11	import org.springframework.web.bind.annotation.RequestBody;
12	
13	/**
14	 * Rejects a create-owner request that is missing or blank in any required field
15	 * (firstName, lastName, address, city, telephone) before {@link BuildOwner} runs.
16	 *
17	 * <p>Binds the body here (the single {@code @RequestBody} for the pipeline) and republishes it
18	 * so later steps read it via {@code @Val}. On failure it throws
19	 * {@link OwnerFieldsValidationException}, which the escalation handler turns into a 400 whose
20	 * {@code errors} array lists each offending field.
21	 */
22	public class ValidateOwnerFields {
23	
24	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
25	            throws OwnerFieldsValidationException {
26	        List<String> errors = new ArrayList<>();
27	        requireText("firstName", request.getFirstName(), errors);
28	        requireText("lastName", request.getLastName(), errors);
29	        normalizeAddress(request, errors);
30	        requireText("city", request.getCity(), errors);
31	        requireText("telephone", request.getTelephone(), errors);
32	        normalizeTelephone(request, errors);
33	        OwnerEmail.normalize(request, errors);
34	        validatePostcode(request, errors);
35	        validateRegistrationDate(request, errors);
36	        if (!errors.isEmpty()) {
37	            throw new OwnerFieldsValidationException(errors);
38	        }
39	        validated.set(request);
40	    }
41	
42	    /**
43	     * Normalizes the supplied address to its canonical form (see {@link AddressNormalizer}) and stores
44	     * it back on the request so later steps persist and return it, and so everything that reads the
45	     * address uses the normalized value.
46	     *
47	     * <p>The structured form is preferred: when a non-blank {@code addressLine1} is supplied, the lines
48	     * are normalized and the composed {@code address} becomes the normalized {@code addressLine1}, with
49	     * a single space and the normalized {@code addressLine2} appended when the latter is present.
50	     * Otherwise the flat {@code address} input is normalized and used (backward-compatible).
51	     *
52	     * <p>The required-field check happens here on the normalized values: a request that carries neither
53	     * a non-blank {@code addressLine1} nor a non-blank flat {@code address} adds an {@code address}
54	     * error (400).
55	     */
56	    private static void normalizeAddress(OwnerFieldsDto request, List<String> errors) {
57	        String line1 = AddressNormalizer.normalize(request.getAddressLine1());
58	        String line2 = AddressNormalizer.normalize(request.getAddressLine2());
59	        String flat = AddressNormalizer.normalize(request.getAddress());
60	        if (!line1.isEmpty()) {
61	            request.setAddressLine1(line1);
62	            request.setAddressLine2(line2.isEmpty() ? null : line2);
63	            request.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
64	        }
65	        else if (!flat.isEmpty()) {
66	            request.setAddress(flat);
67	        }
68	        else {
69	            errors.add("address");
70	        }
71	    }
72	
73	    /**
74	     * Normalizes the telephone to E.164 and stores it back on the request so later steps persist
75	     * and return it. A leading {@code +} and its country code are kept; otherwise country code
76	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
77	     * Spaces, dashes and brackets are stripped, and the result must carry 8 to 15 digits after the
78	     * {@code +}. So {@code "0412 345 678"} becomes {@code "+61412345678"}. A number that cannot form
79	     * valid E.164 adds a {@code telephone} error (400). Skipped when the telephone is missing/blank,
80	     * which {@link #requireText} has already flagged.
81	     */
82	    private static void normalizeTelephone(OwnerFieldsDto request, List<String> errors) {
83	        String telephone = request.getTelephone();
84	        if (telephone == null || telephone.isBlank()) {
85	            return;
86	        }
87	        String e164 = toE164(telephone);
88	        if (e164 == null) {
89	            errors.add("telephone");
90	            return;
91	        }
92	        request.setTelephone(e164);
93	    }
94	
95	    /**
96	     * Returns the E.164 form of {@code telephone}, or {@code null} when it cannot form a valid one.
97	     */
98	    private static String toE164(String telephone) {
99	        String input = telephone.trim();
100	        boolean international = input.startsWith("+");
101	        // strip spaces, dashes and brackets from the remainder
102	        String cleaned = (international ? input.substring(1) : input).replaceAll("[\\s\\-()]", "");
103	        if (!cleaned.matches("\\d+")) {
104	            return null; // stray characters left over — not a phone number
105	        }
106	        String digits;
107	        if (international) {
108	            digits = cleaned;
109	        }
110	        else {
111	            // no country code: assume +61 and drop a single leading national '0'
112	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
113	            digits = "61" + national;
114	        }
115	        if (digits.length() < 8 || digits.length() > 15) {
116	            return null;
117	        }
118	        if (!hasValidNationalLength(digits)) {
119	            return null;
120	        }
121	        return "+" + digits;
122	    }
123	
124	    /**
125	     * Enforces the national-number length required by the country code: {@code +61} needs 9 national
